1	import * as fs from "node:fs";
2	import * as path from "node:path";
3	import { google, gmail_v1 } from "googleapis";
4	import { authorize } from "./gmail-auth";
5	import { summarize, OLLAMA_MODEL } from "./summarize";
6	import { mergeContact } from "./merge";
7	import { splitName } from "./create-contact";
8	import { parseFrontmatterEmails } from "./frontmatter";
9	import {
10	  loadState,
11	  getLastSearched,
12	  setLastSearched,
13	  saveState,
14	} from "./sync-state";
15	
16	// Slice 2 — Incremental per-contact search, READ-ONLY DRY-RUN.
17	//
18	// For each contact file passed as an argument, search Mark's Gmail for the
19	// contact's address(es), derive direction, dedup against entries already in the
20	// file, and PRINT the proposed new "Mark's Email History" entries. Writes
21	// nothing in --dry-run.
22	//
23	//   env "$(op environment read <item-id>)" npm run gmail-sync -- friends/blyth-don.md ...
24	//
25	// The per-contact search cursor (last_searched) lives in .gmail-sync-state.json,
26	// NOT in the contact frontmatter, so a no-op sync produces no git diff. First
27	// run (no cursor yet) searches all history back to the per-category floor; once
28	// a cursor exists it bounds the query with after:.
29	
30	const ROOT = path.resolve(__dirname, "..");
31	
32	// How far back the FIRST run reaches, per category, so an initial scan of a
33	// decades-deep mailbox doesn't take forever. Incremental runs ignore this — they
34	// are bounded by the contact's last_searched cursor instead.
35	const YEARS_BACK: Record<string, number> = {
36	  client: 3,
37	  colleague: 3,
38	  friend: 10,
39	};
40	
41	// Safety cap so a mis-built query can't page forever; we log if we hit it.
42	const MAX_MESSAGES_PER_CONTACT = 2000;
43	
44	// Retry Gmail calls on rate-limit / transient errors with exponential backoff.
45	async function withBackoff<T>(fn: () => Promise<T>, label: string): Promise<T> {
46	  const maxRetries = 6;
47	  let delay = 500;
48	  for (let attempt = 0; ; attempt++) {
49	    try {
50	      return await fn();
51	    } catch (err: unknown) {
52	      const e = err as {
53	        code?: number;
54	        response?: { status?: number };
55	        errors?: Array<{ reason?: string }>;
56	      };
57	      const status = e.code ?? e.response?.status;
58	      const reason = e.errors?.[0]?.reason ?? "";
59	      const retryable =
60	        status === 429 ||
61	        status === 500 ||
62	        status === 503 ||
63	        (status === 403 && /rateLimit|userRateLimit|quota/i.test(reason));
64	      if (!retryable || attempt >= maxRetries) throw err;
65	      const wait = delay + Math.floor(Math.random() * 250);
66	      console.error(
67	        `  ⏳ ${label}: ${status} ${reason} — retry ${attempt + 1}/${maxRetries} in ${wait}ms`
68	      );
69	      await new Promise((r) => setTimeout(r, wait));
70	      delay = Math.min(delay * 2, 16000);
71	    }
72	  }
73	}
74	
75	// ─── Contact file parsing ────────────────────────────────────────────────────
76	
77	interface Contact {
78	  filePath: string;
79	  category: string; // client | friend | colleague
80	  firstName: string | null; // for name-led summaries
81	  needsName: boolean; // true when frontmatter has no first/last name to go on
82	  emails: string[]; // lowercased
83	  lastSearched: string | null; // YYYY-MM-DD cursor from sync-state, or null; set in main()
84	  existingMessageIds: Set<string>; // Gmail hex ids already recorded
85	  existingLegacyKeys: Set<string>; // date|subject|direction|thread for old entries
86	}
87	
88	// Match on a path *segment* so both relative ("friends/x.md") and absolute
89	// paths work — the earlier "/friends/" substring test missed relative args.
90	function categoryFor(contactPath: string): string {
91	  const segs = contactPath.replace(/\\/g, "/").split("/");
92	  if (segs.includes("friends")) return "friend";
93	  if (segs.includes("colleagues")) return "colleague";
94	  return "client";
95	}
96	
97	function unquote(s: string): string {
98	  return s.trim().replace(/^["']|["']$/g, "").trim();
99	}
100	
101	function parseContact(contactPath: string): Contact {
102	  const abs = path.isAbsolute(contactPath)
103	    ? contactPath
104	    : path.join(ROOT, contactPath);
105	  const raw = fs.readFileSync(abs, "utf-8");
106	
107	  const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
108	  if (!fmMatch) throw new Error(`No YAML frontmatter in ${contactPath}`);
109	  const fmLines = fmMatch[1].split(/\r?\n/);
110	
111	  // Addresses: tolerant of email:/emails: and string/list/inline-array shapes.
112	  const emails = parseFrontmatterEmails(fmLines);
113	  let firstName: string | null = null;
114	  let lastName: string | null = null;
115	
116	  for (const line of fmLines) {
117	    const fn = line.match(/^first_name:\s*(.+)$/);
118	    if (fn) {
119	      firstName = unquote(fn[1]) || null;
120	      continue;
121	    }
122	    const ln = line.match(/^last_name:\s*(.+)$/);
123	    if (ln) {
124	      lastName = unquote(ln[1]) || null;
125	      continue;
126	    }
127	  }
128	
129	  // Existing entries: collect Gmail message ids and legacy dedup keys from the
130	  // "## Mark's Email History" section only.
131	  const existingMessageIds = new Set<string>();
132	  const existingLegacyKeys = new Set<string>();
133	  const markSection = raw.split(/^##\s+Mark's Email History\s*$/m)[1];
134	  if (markSection) {
135	    // Cut it off at the next H2 (e.g. "## Email History").
136	    const section = markSection.split(/^##\s+/m)[0];
137	    let curDate = "";
138	    let curSubject = "";
139	    let curDirection = "";
140	    let curThread = "";
141	    let curMessage = "";
142	    const flushLegacy = () => {
143	      if (curSubject && !curMessage) {
144	        existingLegacyKeys.add(
145	          `${curDate}|${curSubject}|${curDirection}|${curThread}`
146	        );
147	      }
148	      curSubject = curDirection = curThread = curMessage = "";
149	    };
150	    for (const line of section.split(/\r?\n/)) {
151	      const dateM = line.match(/^###\s+(\d{4}-\d{2}-\d{2})/);
152	      if (dateM) {
153	        flushLegacy();
154	        curDate = dateM[1];
155	        continue;
156	      }
157	      const subjM = line.match(/^-\s+\*\*Subject:\*\*\s*(.+?)\s*$/);
158	      if (subjM) {
159	        flushLegacy();
160	        curSubject = subjM[1];
161	        continue;
162	      }
163	      const dirM = line.match(/^\s*-\s*Direction:\s*(.+?)\s*$/);
164	      if (dirM) curDirection = dirM[1];
165	      const thrM = line.match(/^\s*-\s*Thread:\s*(.+?)\s*$/);
166	      if (thrM) curThread = thrM[1];
167	      const msgM = line.match(/^\s*-\s*Message:\s*(.+?)\s*$/);
168	      if (msgM) {
169	        curMessage = msgM[1];
170	        existingMessageIds.add(curMessage);
171	      }
172	    }
173	    flushLegacy();
174	  }
175	
176	  return {
177	    filePath: contactPath,
178	    category: categoryFor(contactPath),
179	    firstName,
180	    needsName: !firstName && !lastName,
181	    emails,
182	    lastSearched: null, // filled from sync-state in main()
183	    existingMessageIds,
184	    existingLegacyKeys,
185	  };
186	}
187	
188	// ─── Header helpers ──────────────────────────────────────────────────────────
189	
190	function decodeRFC2047(s: string): string {
191	  return s.replace(
192	    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
193	    (_m, charset, enc, encoded) => {
194	      try {
195	        if (enc.toUpperCase() === "B") {
196	          return Buffer.from(encoded, "base64").toString(
197	            charset.toLowerCase() === "utf-8" ? "utf-8" : "latin1"
198	          );
199	        }
200	        return encoded
201	          .replace(/_/g, " ")
202	          .replace(/=([0-9A-Fa-f]{2})/g, (_x: string, h: string) =>
203	            String.fromCharCode(parseInt(h, 16))
204	          );
205	      } catch {
206	        return encoded;
207	      }
208	    }
209	  );
210	}
211	
212	// Extract lowercased email addresses from a header value.
213	function addressesIn(headerValue: string): string[] {
214	  const out: string[] = [];
215	  const re = /[\w.+\-]+@[\w.\-]+\.\w+/g;
216	  let m: RegExpExecArray | null;
217	  while ((m = re.exec(headerValue)) !== null) out.push(m[0].toLowerCase());
218	  return out;
219	}
220	
221	function headerValue(
222	  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
223	  name: string
224	): string {
225	  const h = headers?.find((x) => (x.name ?? "").toLowerCase() === name);
226	  return h?.value ?? "";
227	}
228	
229	// Split a header's address list on commas that aren't inside a quoted display
230	// name (e.g. `"Harris, Josh" <josh@x.com>, else@y.com`).
231	export function splitAddressList(headerValue: string): string[] {
232	  const parts: string[] = [];
233	  let quoted = false;
234	  let cur = "";
235	  for (const ch of headerValue) {
236	    if (ch === '"') quoted = !quoted;
237	    if (ch === "," && !quoted) {
238	      parts.push(cur);
239	      cur = "";
240	    } else {
241	      cur += ch;
242	    }
243	  }
244	  if (cur.trim()) parts.push(cur);
245	  return parts;
246	}
247	
248	// Pull the display name paired with a specific address out of a From/To/Cc
249	// header, e.g. `"Josh Harris" <josh@x.com>` → "Josh Harris".
250	export function displayNameFor(headerVal: string, wantedEmails: Set<string>): string | null {
251	  for (const part of splitAddressList(decodeRFC2047(headerVal))) {
252	    const m = part.match(/^\s*"?([^"<]*?)"?\s*<\s*([^>]+?)\s*>\s*$/);
253	    if (!m) continue;
254	    const name = m[1].trim();
255	    const email = m[2].trim().toLowerCase();
256	    if (name && wantedEmails.has(email)) return name;
257	  }
258	  return null;
259	}
260	
261	// Look across From/To/Cc for a display name belonging to one of the contact's
262	// addresses — used to backfill a name for contacts recorded with only an email.
263	export function findDisplayName(
264	  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
265	  contactEmails: Set<string>
266	): string | null {
267	  for (const field of ["from", "to", "cc"]) {
268	    const name = displayNameFor(headerValue(headers, field), contactEmails);
269	    if (name) return name;
270	  }
271	  return null;
272	}
273	
274	// ─── Direction ───────────────────────────────────────────────────────────────
275	
276	// Mark sent it (Gmail SENT label, authoritative across all of Mark's historical
277	// addresses) → "To {cat}". Else contact is the sender → "From {cat}". Else Mark
278	// is only a recipient on a thread neither he nor the contact started → "CC'd".
279	function deriveDirection(
280	  labelIds: string[],
281	  fromAddrs: string[],
282	  contactEmails: Set<string>,
283	  category: string
284	): string {
285	  if (labelIds.includes("SENT")) return `To ${category}`;
286	  if (fromAddrs.some((a) => contactEmails.has(a))) return `From ${category}`;
287	  return "CC'd";
288	}
289	
290	// ─── Proposed entry ──────────────────────────────────────────────────────────
291	
292	interface ProposedEntry {
293	  ts: number; // internalDate ms, for exact ordering within a day
294	  dateStr: string;
295	  subject: string;
296	  direction: string;
297	  threadId: string;
298	  messageId: string;
299	  link: string;
300	  summary?: string; // filled by --summarize
301	}
302	
303	function legacyKey(e: ProposedEntry): string {
304	  return `${e.dateStr}|${e.subject}|${e.direction}|${e.threadId}`;
305	}
306	
307	// ─── Gmail search ────────────────────────────────────────────────────────────
308	
309	// The lower bound for a contact's search: last_searched if we have one,
310	// otherwise the per-category first-run floor (today − N years). Returns
311	// YYYY-MM-DD.
312	function effectiveAfter(contact: Contact, today: string): string {
313	  if (contact.lastSearched) return contact.lastSearched;
314	  const years = YEARS_BACK[contact.category] ?? 3;
315	  const d = new Date(today);
316	  d.setFullYear(d.getFullYear() - years);
317	  return d.toISOString().slice(0, 10);
318	}
319	
320	function buildQuery(contact: Contact, today: string): string {
321	  const addrs = contact.emails.join(" OR ");
322	  const clauses = `(from:(${addrs}) OR to:(${addrs}) OR cc:(${addrs}))`;
323	  const after = effectiveAfter(contact, today).replace(/-/g, "/"); // YYYY/MM/DD
324	  return `after:${after} ${clauses}`;
325	}
326	
327	async function searchContact(
328	  gmail: gmail_v1.Gmail,
329	  contact: Contact,
330	  today: string,
331	  wantName: boolean
332	): Promise<{ entries: ProposedEntry[]; capped: boolean; discoveredName: string | null }> {
333	  const q = buildQuery(contact, today);
334	  const ids: { id: string; threadId: string }[] = [];
335	  let pageToken: string | undefined;
336	  let capped = false;
337	
338	  do {
339	    const res = await withBackoff(
340	      () =>
341	        gmail.users.messages.list({
342	          userId: "me",
343	          q,
344	          maxResults: 500,
345	          pageToken,
346	        }),
347	      "messages.list"
348	    );
349	    for (const m of res.data.messages ?? []) {
350	      if (m.id && m.threadId) ids.push({ id: m.id, threadId: m.threadId });
351	    }
352	    pageToken = res.data.nextPageToken ?? undefined;
353	    if (ids.length >= MAX_MESSAGES_PER_CONTACT) {
354	      capped = true;
355	      break;
356	    }
357	  } while (pageToken);
358	
359	  const contactEmails = new Set(contact.emails);
360	  const entries: ProposedEntry[] = [];
361	  let discoveredName: string | null = null;
362	
363	  for (const { id } of ids) {
364	    const msg = await withBackoff(
365	      () =>
366	        gmail.users.messages.get({
367	          userId: "me",
368	          id,
369	          format: "metadata",
370	          metadataHeaders: ["From", "To", "Cc", "Subject", "Date"],
371	        }),
372	      `messages.get ${id}`
373	    );
374	    const labelIds = msg.data.labelIds ?? [];
375	    // Skip drafts — not a sent or received email.
376	    if (labelIds.includes("DRAFT")) continue;
377	
378	    const headers = msg.data.payload?.headers;
379	    if (wantName && !discoveredName) {
380	      discoveredName = findDisplayName(headers, contactEmails);
381	    }
382	    const fromAddrs = addressesIn(headerValue(headers, "from"));
383	    const subject =
384	      decodeRFC2047(headerValue(headers, "subject")).trim() || "(no subject)";
385	    const ts = Number(msg.data.internalDate ?? 0);
386	    const dateStr = new Date(ts).toISOString().slice(0, 10);
387	    const threadId = msg.data.threadId ?? "";
388	    const messageId = msg.data.id ?? "";
389	    const direction = deriveDirection(
390	      labelIds,
391	      fromAddrs,
392	      contactEmails,
393	      contact.category
394	    );
395	
396	    entries.push({
397	      ts,
398	      dateStr,
399	      subject,
400	      direction,
401	      threadId,
402	      messageId,
403	      link: `https://mail.google.com/mail/u/0/#all/${messageId}?authuser=mark@felicisholdings.com`,
404	    });
405	  }
406	
407	  // Newest first, by exact timestamp.
408	  entries.sort((a, b) => b.ts - a.ts);
409	  return { entries, capped, discoveredName };
410	}
411	
412	// ─── Dry-run report ──────────────────────────────────────────────────────────
413	
414	function renderEntry(e: ProposedEntry): string {
415	  const lines = [`- **Subject:** ${e.subject}`, `  - Direction: ${e.direction}`];
416	  if (e.summary) lines.push(`  - Summary: ${e.summary}`);
417	  lines.push(`  - Thread: ${e.threadId}`);
418	  lines.push(`  - Message: ${e.messageId}`);
419	  lines.push(`  - Link: ${e.link}`);
420	  return lines.join("\n");
421	}
422	
423	// Every contact file across all categories, alphabetical (stable resume order).
424	function discoverAllContacts(): string[] {
425	  const files: string[] = [];
426	  for (const dir of ["client", "colleagues", "friends"]) {
427	    const abs = path.join(ROOT, dir);
428	    if (!fs.existsSync(abs)) continue;
429	    for (const f of fs.readdirSync(abs)) {
430	      if (f.endsWith(".md")) files.push(`${dir}/${f}`);
431	    }
432	  }
433	  return files.sort();
434	}
435	
436	async function main() {
437	  const rawArgs = process.argv.slice(2);
438	  if (rawArgs.includes("--help")) {
439	    console.error(
440	      "Usage: npm run gmail-sync -- [contact.md ...]\n" +
441	        "With no file args, scans ALL contacts in client/, colleagues/, friends/.\n" +
442	        "By default: searches Gmail, generates summaries, and WRITES the files (advances last_searched).\n" +
443	        "  --dry-run       read-only preview — write nothing\n" +
444	        "  --no-summarize  skip the local-model Summary line"
445	    );
446	    process.exit(0);
447	  }
448	  // Default behavior: summarize + write. Opt out per run.
449	  const writeFlag = !rawArgs.includes("--dry-run");
450	  const summarizeFlag = !rawArgs.includes("--no-summarize");
451	  const fileArgs = rawArgs.filter((a) => !a.startsWith("--"));
452	  const contactFiles = fileArgs.length > 0 ? fileArgs : discoverAllContacts();
453	  if (contactFiles.length === 0) {
454	    console.error("No contact files found.");
455	    process.exit(1);
456	  }
457	  if (fileArgs.length === 0) {
458	    console.error(`No files given — scanning all ${contactFiles.length} contacts.`);
459	  }
460	
461	  const today = new Date().toISOString().slice(0, 10);
462	  // Per-contact search cursors live outside the contact files (see sync-state).
463	  const state = loadState();
464	  console.error("Authorizing (read-only)...");
465	  const auth = await authorize();
466	  const gmail = google.gmail({ version: "v1", auth });
467	
468	  // End-of-run summary: most contacts have nothing new, so track just the ones
469	  // that changed (or would change, in --dry-run) plus any we couldn't write.
470	  const changed: { file: string; count: number }[] = [];
471	  const skippedMalformed: string[] = [];
472	
473	  for (const arg of contactFiles) {
474	    const contact = parseContact(arg);
475	    contact.lastSearched = getLastSearched(state, arg);
476	    console.log(`\n${"═".repeat(72)}`);
477	    console.log(`Contact: ${contact.filePath}  [${contact.category}]`);
478	    console.log(`Addresses: ${contact.emails.join(", ") || "(none!)"}`);
479	    const after = effectiveAfter(contact, today);
480	    console.log(
481	      `Search bound: after ${after} ${
482	        contact.lastSearched
483	          ? "(incremental, from last_searched)"
484	          : `(first run, ${YEARS_BACK[contact.category] ?? 3}yr ${contact.category} floor)`
485	      }`
486	    );
487	
488	    if (contact.emails.length === 0) {
489	      console.log("⚠️  No addresses in frontmatter — skipping.");
490	      continue;
491	    }
492	
493	    const { entries, capped, discoveredName } = await searchContact(
494	      gmail,
495	      contact,
