501	        `⚠️  Hit the ${MAX_MESSAGES_PER_CONTACT}-message safety cap — results truncated.`
502	      );
503	    }
504	
505	    let nameFields: Record<string, string> | undefined;
506	    if (contact.needsName && discoveredName) {
