1	// Creates a new contact markdown file from template.md for a brand-new
2	// contact (e.g. one discovered via a Gmail label with no existing file — see
3	// "Full Repo Access" / "Gmail Labels for Category Routing" in CLAUDE.md).
4	// gmail-sync only updates contacts that already have a file; this script is
5	// the manual step that creates one.
6	import * as fs from "node:fs";
7	import * as path from "node:path";
8	
9	const ROOT = path.resolve(__dirname, "..");
10	const TEMPLATE_PATH = path.join(ROOT, "template.md");
11	
12	export const CATEGORY_DIRS: Record<string, string> = {
13	  client: "client",
14	  colleague: "colleagues",
15	  friend: "friends",
16	};
17	
18	export function slugify(s: string): string {
19	  return s
20	    .toLowerCase()
21	    .normalize("NFD")
22	    .replace(/[\u0300-\u036f]/g, "") // strip accents
23	    .replace(/[^a-z0-9]+/g, "-")
24	    .replace(/^-+|-+$/g, "");
25	}
26	
27	export function makeFilename(
28	  lastName: string,
29	  firstName: string,
30	  email: string,
31	  usedFilenames: Set<string>
32	): string {
33	  let base: string;
34	  if (lastName && firstName) {
35	    base = slugify(`${lastName}-${firstName}`);
36	  } else if (lastName) {
37	    base = slugify(lastName);
38	  } else if (firstName) {
39	    base = slugify(firstName);
40	  } else {
41	    base = slugify(email.split("@")[0]);
42	  }
43	  if (!base) base = slugify(email.replace("@", "-at-"));
44	
45	  let filename = base;
46	  if (usedFilenames.has(filename)) {
47	    const domain = email.split("@")[1]?.split(".")[0] || "dup";
48	    filename = `${base}-${slugify(domain)}`;
49	  }
50	  let final = filename;
51	  let counter = 2;
52	  while (usedFilenames.has(final)) {
53	    final = `${filename}-${counter}`;
54	    counter++;
55	  }
56	  return `${final}.md`;
57	}
58	
59	export function splitName(name: string): { firstName: string; lastName: string } {
60	  const parts = name.trim().split(/\s+/).filter(Boolean);
61	  if (parts.length === 0) return { firstName: "", lastName: "" };
62	  if (parts.length === 1) return { firstName: parts[0], lastName: "" };
63	  return { firstName: parts.slice(0, -1).join(" "), lastName: parts[parts.length - 1] };
64	}
65	
66	export function buildFrontmatter(
67	  lastName: string,
68	  firstName: string,
69	  emails: string[],
70	  today: string
71	): string {
72	  const lines = ["---"];
73	  lines.push(`last_name: ${lastName}`);
74	  lines.push(`first_name: ${firstName}`);
75	  // One key for every shape — `email:` reads back the same whether it holds a
76	  // single string or a block list (see parseFrontmatterEmails), so humans never
77	  // have to remember the `emails:` variant.
78	  if (emails.length > 1) {
79	    lines.push("email:");
80	    for (const e of emails) lines.push(`  - "${e}"`);
81	  } else {
82	    lines.push(`email: "${emails[0]}"`);
83	  }
