1	import { simpleParser } from "mailparser";
2	import { Ollama } from "ollama";
3	
4	// Slice 3 — one-sentence email summaries via a LOCAL Ollama model.
5	// Email bodies never leave the machine. A failed/low-confidence summary returns
6	// null (caller writes no Summary line) — never a fabricated one.
7	
8	const MODEL = process.env.OLLAMA_MODEL ?? "qwen3.5:9b-mlx";
9	const OLLAMA_HOST = process.env.OLLAMA_HOST ?? "http://127.0.0.1:11434";
10	
11	// Qwen3-family models are dual-mode; for a one-sentence summary we want the
12	// non-thinking path (no <think> block, faster). Auto-disable thinking for any
13	// qwen3 model; override with OLLAMA_THINK=true|false. undefined = don't send the
14	// flag (correct for non-thinking models like llama3.2).
15	const THINK: boolean | undefined =
16	  process.env.OLLAMA_THINK != null
17	    ? process.env.OLLAMA_THINK === "true"
18	    : /qwen3/i.test(MODEL)
19	      ? false
20	      : undefined;
21	const REQUEST_TIMEOUT_MS = 60_000;
22	const BODY_CHAR_CAP = 2000;
23	const SUMMARY_CHAR_CAP = 320; // safety net only; the prompt asks for ~30 words
24	
25	const ollama = new Ollama({ host: OLLAMA_HOST });
26	
27	// ─── Body extraction ─────────────────────────────────────────────────────────
28	
29	// Keep only the new top content: cut at the first quoted-reply marker or
30	// signature so the summary reflects THIS message, not the whole quoted chain.
31	function stripQuoted(text: string): string {
32	  const cutMarkers = [
33	    /^\s*On .+ wrote:\s*$/i,
34	    /^\s*-{2,}\s*Original Message\s*-{2,}/i,
35	    /^\s*From:\s.+/i, // Outlook-style forwarded header block
36	    /^\s*_{5,}\s*$/,
37	    /^\s*>+/, // quoted lines
38	    /^\s*--\s*$/, // signature delimiter
39	    /^\s*Sent from my /i,
40	  ];
41	  const out: string[] = [];
42	  for (const line of text.split(/\r?\n/)) {
43	    if (cutMarkers.some((re) => re.test(line))) break;
44	    out.push(line);
45	  }
46	  return out.join("\n").trim();
47	}
48	
49	async function extractBody(rawBase64url: string): Promise<string> {
50	  const parsed = await simpleParser(Buffer.from(rawBase64url, "base64url"));
51	  const text = (parsed.text ?? "").trim();
52	  const stripped = stripQuoted(text) || text; // fall back if stripping nukes all
53	  return stripped.slice(0, BODY_CHAR_CAP).trim();
54	}
55	
56	// ─── Prompt & output ─────────────────────────────────────────────────────────
57	
58	export interface SummarizeInput {
59	  rawBase64url: string;
60	  direction: string; // "To client" | "From friend" | "CC'd" | ...
61	  category: string; // client | friend | colleague
62	  firstName: string | null;
63	  subject: string;
64	}
65	
66	function buildPrompt(body: string, input: SummarizeInput): string {
67	  const contactLabel = input.firstName || `the ${input.category}`;
68	  let framing: string;
69	  if (input.direction.startsWith("To ")) {
70	    framing =
71	      `Mark wrote this email TO ${contactLabel} (Mark's ${input.category}). ` +
72	      `Summarize what MARK says to ${contactLabel}, and start the sentence with "Mark".`;
73	  } else if (input.direction.startsWith("From ")) {
74	    framing =
75	      `${contactLabel} (Mark's ${input.category}) wrote this email TO Mark. ` +
76	      `Summarize what ${contactLabel} says to Mark, and start the sentence with "${contactLabel}".`;
77	  } else {
78	    framing = "Summarize this email from the perspective of whoever sent it.";
79	  }
80	  return [
81	    "Summarize the following email in ONE concise sentence of at most about 30 words.",
82	    framing,
83	    "Do not confuse the sender with the recipient. Describe what the message actually says. " +
84	      "No preamble, no quotes, no subject line — output only the single sentence.",
85	    "",
86	    `Subject: ${input.subject}`,
87	    "Email body:",
88	    body,
89	  ].join("\n");
90	}
91	
92	function cleanOutput(raw: string): string | null {
93	  let s = (raw ?? "").trim();
94	  if (!s) return null;
95	  // First non-empty line only.
96	  s = s.split(/\r?\n/).map((l) => l.trim()).find(Boolean) ?? "";
97	  s = s.replace(/^(summary|here(?:'|)s (?:a|the) summary)\s*[:\-]\s*/i, "");
98	  s = s.replace(/^["'`*]+|["'`*]+$/g, "").trim();
99	  if (s.length < 5) return null;
100	  // Over-length safety net: truncate on a WORD boundary (never mid-word) and
101	  // mark it with an ellipsis rather than a fake period.
102	  if (s.length > SUMMARY_CHAR_CAP) {
103	    let cut = s.slice(0, SUMMARY_CHAR_CAP);
104	    const lastSpace = cut.lastIndexOf(" ");
105	    if (lastSpace > 40) cut = cut.slice(0, lastSpace);
106	    s = cut.replace(/[\s,;:]+$/, "") + "…";
107	  }
108	  if (!/[.!?…]$/.test(s)) s += ".";
109	  return s;
110	}
111	
112	// ─── Ollama call ─────────────────────────────────────────────────────────────
113	
114	function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
115	  return Promise.race([
116	    p,
117	    new Promise<T>((_, reject) =>
118	      setTimeout(() => reject(new Error("ollama request timed out")), ms)
119	    ),
120	  ]);
121	}
122	
123	function isConnRefused(err: unknown): boolean {
124	  const e = err as { cause?: { code?: string }; code?: string; message?: string };
125	  return (
126	    e?.cause?.code === "ECONNREFUSED" ||
127	    e?.code === "ECONNREFUSED" ||
128	    /ECONNREFUSED|fetch failed/i.test(e?.message ?? "")
129	  );
130	}
131	
132	function ollamaDownError(): Error {
133	  return new Error(
134	    `Cannot reach Ollama at ${OLLAMA_HOST}. Start it with \`ollama serve\` and ` +
135	      `ensure the model is pulled: \`ollama pull ${MODEL}\`.`
136	  );
137	}
138	
139	async function generate(prompt: string, temperature: number): Promise<string> {
140	  const res = await ollama.chat({
141	    model: MODEL,
142	    messages: [{ role: "user", content: prompt }],
143	    options: { temperature },
144	    stream: false,
145	    ...(THINK !== undefined ? { think: THINK } : {}),
146	  });
147	  return res.message?.content ?? "";
148	}
149	
150	// Returns a one-sentence summary, or null if the model can't produce a good one
151	// (caller then writes no Summary line and it's retried on a later pass).
152	// Throws only when Ollama is unreachable (fail fast).
153	export async function summarize(input: SummarizeInput): Promise<string | null> {
154	  const body = await extractBody(input.rawBase64url);
155	  if (!body) return null;
156	  const prompt = buildPrompt(body, input);
157	
158	  for (const temperature of [0.2, 0.0]) {
159	    try {
