import { simpleParser } from "mailparser";
import { Ollama } from "ollama";

// Slice 3 — one-sentence email summaries via a LOCAL Ollama model.
// Email bodies never leave the machine. A failed/low-confidence summary returns
// null (caller writes no Summary line) — never a fabricated one.

const MODEL = process.env.OLLAMA_MODEL ?? "qwen3.5:9b-mlx";
const OLLAMA_HOST = process.env.OLLAMA_HOST ?? "http://127.0.0.1:11434";

// Qwen3-family models are dual-mode; for a one-sentence summary we want the
// non-thinking path (no <think> block, faster). Auto-disable thinking for any
// qwen3 model; override with OLLAMA_THINK=true|false. undefined = don't send the
// flag (correct for non-thinking models like llama3.2).
const THINK: boolean | undefined =
  process.env.OLLAMA_THINK != null
    ? process.env.OLLAMA_THINK === "true"
    : /qwen3/i.test(MODEL)
      ? false
      : undefined;
const REQUEST_TIMEOUT_MS = 60_000;
const BODY_CHAR_CAP = 2000;
const SUMMARY_CHAR_CAP = 320; // safety net only; the prompt asks for ~30 words

const ollama = new Ollama({ host: OLLAMA_HOST });

// ─── Body extraction ─────────────────────────────────────────────────────────

// Keep only the new top content: cut at the first quoted-reply marker or
// signature so the summary reflects THIS message, not the whole quoted chain.
function stripQuoted(text: string): string {
  const cutMarkers = [
    /^\s*On .+ wrote:\s*$/i,
    /^\s*-{2,}\s*Original Message\s*-{2,}/i,
    /^\s*From:\s.+/i, // Outlook-style forwarded header block
    /^\s*_{5,}\s*$/,
    /^\s*>+/, // quoted lines
    /^\s*--\s*$/, // signature delimiter
    /^\s*Sent from my /i,
  ];
  const out: string[] = [];
  for (const line of text.split(/\r?\n/)) {
    if (cutMarkers.some((re) => re.test(line))) break;
    out.push(line);
  }
  return out.join("\n").trim();
}

async function extractBody(rawBase64url: string): Promise<string> {
  const parsed = await simpleParser(Buffer.from(rawBase64url, "base64url"));
  const text = (parsed.text ?? "").trim();
  const stripped = stripQuoted(text) || text; // fall back if stripping nukes all
  return stripped.slice(0, BODY_CHAR_CAP).trim();
}

// ─── Prompt & output ─────────────────────────────────────────────────────────

export interface SummarizeInput {
  rawBase64url: string;
  direction: string; // "To client" | "From friend" | "CC'd" | ...
  category: string; // client | friend | colleague
  firstName: string | null;
  subject: string;
}

function buildPrompt(body: string, input: SummarizeInput): string {
  const contactLabel = input.firstName || `the ${input.category}`;
  let framing: string;
  if (input.direction.startsWith("To ")) {
    framing =
      `Mark wrote this email TO ${contactLabel} (Mark's ${input.category}). ` +
      `Summarize what MARK says to ${contactLabel}, and start the sentence with "Mark".`;
  } else if (input.direction.startsWith("From ")) {
    framing =
      `${contactLabel} (Mark's ${input.category}) wrote this email TO Mark. ` +
      `Summarize what ${contactLabel} says to Mark, and start the sentence with "${contactLabel}".`;
  } else {
    framing = "Summarize this email from the perspective of whoever sent it.";
  }
  return [
    "Summarize the following email in ONE concise sentence of at most about 30 words.",
    framing,
    "Do not confuse the sender with the recipient. Describe what the message actually says. " +
      "No preamble, no quotes, no subject line — output only the single sentence.",
    "",
    `Subject: ${input.subject}`,
    "Email body:",
    body,
  ].join("\n");
}

function cleanOutput(raw: string): string | null {
  let s = (raw ?? "").trim();
  if (!s) return null;
  // First non-empty line only.
  s = s.split(/\r?\n/).map((l) => l.trim()).find(Boolean) ?? "";
  s = s.replace(/^(summary|here(?:'|)s (?:a|the) summary)\s*[:\-]\s*/i, "");
  s = s.replace(/^["'`*]+|["'`*]+$/g, "").trim();
  if (s.length < 5) return null;
  // Over-length safety net: truncate on a WORD boundary (never mid-word) and
  // mark it with an ellipsis rather than a fake period.
  if (s.length > SUMMARY_CHAR_CAP) {
    let cut = s.slice(0, SUMMARY_CHAR_CAP);
    const lastSpace = cut.lastIndexOf(" ");
    if (lastSpace > 40) cut = cut.slice(0, lastSpace);
    s = cut.replace(/[\s,;:]+$/, "") + "…";
  }
  if (!/[.!?…]$/.test(s)) s += ".";
  return s;
}

// ─── Ollama call ─────────────────────────────────────────────────────────────

function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  return Promise.race([
    p,
    new Promise<T>((_, reject) =>
      setTimeout(() => reject(new Error("ollama request timed out")), ms)
    ),
  ]);
}

function isConnRefused(err: unknown): boolean {
  const e = err as { cause?: { code?: string }; code?: string; message?: string };
  return (
    e?.cause?.code === "ECONNREFUSED" ||
    e?.code === "ECONNREFUSED" ||
    /ECONNREFUSED|fetch failed/i.test(e?.message ?? "")
  );
}

function ollamaDownError(): Error {
  return new Error(
    `Cannot reach Ollama at ${OLLAMA_HOST}. Start it with \`ollama serve\` and ` +
      `ensure the model is pulled: \`ollama pull ${MODEL}\`.`
  );
}

async function generate(prompt: string, temperature: number): Promise<string> {
  const res = await ollama.chat({
    model: MODEL,
    messages: [{ role: "user", content: prompt }],
    options: { temperature },
    stream: false,
    ...(THINK !== undefined ? { think: THINK } : {}),
  });
  return res.message?.content ?? "";
}

// Returns a one-sentence summary, or null if the model can't produce a good one
// (caller then writes no Summary line and it's retried on a later pass).
// Throws only when Ollama is unreachable (fail fast).
export async function summarize(input: SummarizeInput): Promise<string | null> {
  const body = await extractBody(input.rawBase64url);
  if (!body) return null;
  const prompt = buildPrompt(body, input);

  for (const temperature of [0.2, 0.0]) {
    try {
      const out = await withTimeout(generate(prompt, temperature), REQUEST_TIMEOUT_MS);
      const cleaned = cleanOutput(out);
      if (cleaned) return cleaned;
    } catch (err) {
      if (isConnRefused(err)) throw ollamaDownError();
      // timeout / transient — fall through to the retry, then give up
    }
  }
  return null;
}

export const OLLAMA_MODEL = MODEL;

