// `@protechtraining.com` → true; `josh@x.com` → false. A bare "@" is not a
// wildcard (it would match every address on earth).
export function isDomainWildcard(entry: string): boolean {
  return entry.startsWith("@") && entry.length > 1;
}

export interface AddressMatcher {
  hasWildcard: boolean;
  matches(address: string): boolean;
}

// Turns a contact's frontmatter entries into an address test. Exact addresses
// match exactly; a `@domain.com` wildcard matches that domain AND its
// subdomains (`joe@mail.domain.com`) — an org's mail often leaves from more
// than one host. It deliberately does NOT match a lookalike suffix, so
// `@protechtraining.com` never matches `bad@notprotechtraining.com`.
export function makeAddressMatcher(entries: string[]): AddressMatcher {
  const exact = new Set<string>();
  const domains: string[] = [];
  for (const e of entries) {
    const v = e.toLowerCase();
    if (isDomainWildcard(v)) domains.push(v.slice(1));
    else exact.add(v);
  }
  return {
    hasWildcard: domains.length > 0,
    matches(address: string): boolean {
      const a = address.toLowerCase();
      if (exact.has(a)) return true;
      const at = a.lastIndexOf("@");
      if (at === -1) return false;
      const host = a.slice(at + 1);
      return domains.some((d) => host === d || host.endsWith(`.${d}`));
    },
  };
}

