// Which contact file "owns" each exact address in the repo. A person with their
// own file wins over an org wildcard that covers their domain, so their mail
// lands in exactly one file. Wildcards themselves claim nothing — they're the
// fallback, not the owner.
export function buildOwnershipMap(
  files: string[],
  readEmails: (file: string) => string[]
): Map<string, Set<string>> {
  const owners = new Map<string, Set<string>>();
  for (const file of files) {
    for (const e of readEmails(file)) {
      if (isDomainWildcard(e)) continue;
      const set = owners.get(e) ?? new Set<string>();
      set.add(file);
      owners.set(e, set);
    }
  }
  return owners;
}

