// else's file. Only meaningful for wildcard contacts.
export function excludedFor(
  contact: Pick<Contact, "filePath" | "matcher">,
  owners: Map<string, Set<string>>
): Set<string> {
  const out = new Set<string>();
  if (!contact.matcher.hasWildcard) return out;
  for (const [address, files] of owners) {
    if (!contact.matcher.matches(address)) continue;
    if (files.size === 1 && files.has(contact.filePath)) continue; // its own
    out.add(address);
  }
  return out;
}

