// Pull the display name paired with a specific address out of a From/To/Cc
// header, e.g. `"Josh Harris" <josh@x.com>` → "Josh Harris".
export function displayNameFor(headerVal: string, wantedEmails: Set<string>): string | null {
  for (const part of splitAddressList(decodeRFC2047(headerVal))) {
    const m = part.match(/^\s*"?([^"<]*?)"?\s*<\s*([^>]+?)\s*>\s*$/);
    if (!m) continue;
    const name = m[1].trim();
    const email = m[2].trim().toLowerCase();
    if (name && wantedEmails.has(email)) return name;
  }
  return null;
}

