function relFromRoot(p: string): string {
  const abs = path.isAbsolute(p) ? p : path.join(ROOT, p);
  return path.relative(ROOT, abs).replace(/\\/g, "/");
}

// Just the frontmatter addresses — cheaper than parseContact for the ownership
// sweep, which has to read every file in the repo, not just the ones we sync.
function readFrontmatterEmails(relPath: string): string[] {
  const raw = fs.readFileSync(path.join(ROOT, relPath), "utf-8");
  const fm = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  return fm ? parseFrontmatterEmails(fm[1].split(/\r?\n/)) : [];
}

