  client: "client",
  colleague: "colleagues",
  friend: "friends",
  partner: "partners",
};

export function slugify(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // strip accents
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function makeFilename(
  lastName: string,
  firstName: string,
  email: string,
  usedFilenames: Set<string>
): string {
  let base: string;
  if (lastName && firstName) {
    base = slugify(`${lastName}-${firstName}`);
  } else if (lastName) {
    base = slugify(lastName);
  } else if (firstName) {
    base = slugify(firstName);
  } else if (isDomainWildcard(email)) {
    // No name on an org file — "@protechtraining.com" → protechtraining.md.
    base = slugify(email.slice(1).split(".")[0]);
  } else {
    base = slugify(email.split("@")[0]);
  }
  if (!base) base = slugify(email.replace("@", "-at-"));

  let filename = base;
  if (usedFilenames.has(filename)) {
    const domain = email.split("@")[1]?.split(".")[0] || "dup";
    filename = `${base}-${slugify(domain)}`;
  }
  let final = filename;
  let counter = 2;
  while (usedFilenames.has(final)) {
    final = `${filename}-${counter}`;
    counter++;
  }
  return `${final}.md`;
}

