import { describe, it, expect } from "vitest";
import { parseFrontmatterEmails } from "./frontmatter";

const lines = (s: string) => s.split("\n");

describe("parseFrontmatterEmails", () => {
  it("reads a block list under the singular email: key (the ross-mark case)", () => {
    expect(
      parseFrontmatterEmails(
        lines(`last_name: Ross\nemail:\n  - "mross@sehcomp.ca"\n  - "markjross@outlook.com"\nlast_updated: 2026-07-03`)
      )
    ).toEqual(["mross@sehcomp.ca", "markjross@outlook.com"]);
  });

  it("reads a block list under the plural emails: key (backward compat)", () => {
    expect(
      parseFrontmatterEmails(lines(`emails:\n  - "a@x.com"\n  - "b@y.com"`))
    ).toEqual(["a@x.com", "b@y.com"]);
  });

  it("reads a single inline string", () => {
    expect(parseFrontmatterEmails(lines(`email: "solo@x.com"`))).toEqual([
      "solo@x.com",
    ]);
  });

  it("reads an inline array under either key", () => {
    expect(
      parseFrontmatterEmails(lines(`email: ["a@x.com", "b@y.com"]`))
    ).toEqual(["a@x.com", "b@y.com"]);
  });

  it("lowercases addresses", () => {
    expect(parseFrontmatterEmails(lines(`email: "Mixed@Case.COM"`))).toEqual([
      "mixed@case.com",
    ]);
  });

  it("returns [] when there is no email key", () => {
    expect(parseFrontmatterEmails(lines(`last_name: Ross\nfirst_name: Mark`))).toEqual(
      []
    );
  });
});

