import { describe, it, expect } from "vitest";
import { splitAddressList, displayNameFor, findDisplayName } from "./gmail-sync";

describe("splitAddressList", () => {
  it("splits plain comma-separated addresses", () => {
    expect(splitAddressList("a@x.com, b@y.com")).toEqual(["a@x.com", " b@y.com"]);
  });

  it("does not split on a comma inside a quoted display name", () => {
    const parts = splitAddressList('"Harris, Josh" <josh@x.com>, else@y.com');
    expect(parts).toEqual(['"Harris, Josh" <josh@x.com>', " else@y.com"]);
  });
});

describe("displayNameFor", () => {
  it("returns the display name paired with the wanted address", () => {
    const header = '"Josh Harris" <josh@x.com>, Someone Else <other@y.com>';
    expect(displayNameFor(header, new Set(["josh@x.com"]))).toBe("Josh Harris");
  });

  it("decodes an RFC 2047 encoded display name", () => {
    const header = "=?UTF-8?B?Sm9zaCBIYXJyaXM=?= <josh@x.com>";
    expect(displayNameFor(header, new Set(["josh@x.com"]))).toBe("Josh Harris");
  });

  it("returns null when the address has no display name", () => {
    expect(displayNameFor("josh@x.com", new Set(["josh@x.com"]))).toBeNull();
  });

  it("returns null when the address doesn't match", () => {
    const header = '"Josh Harris" <josh@x.com>';
    expect(displayNameFor(header, new Set(["someoneelse@x.com"]))).toBeNull();
  });
});

describe("findDisplayName", () => {
  const headers = [
    { name: "From", value: "josh@x.com" },
    { name: "To", value: '"Josh Harris" <josh@x.com>, mark@felicisholdings.com' },
    { name: "Cc", value: "" },
  ];

  it("falls back to To/Cc when From has no display name", () => {
    expect(findDisplayName(headers, new Set(["josh@x.com"]))).toBe("Josh Harris");
  });

  it("returns null when no header carries a matching display name", () => {
    expect(findDisplayName(headers, new Set(["nobody@x.com"]))).toBeNull();
  });
});

