});

input.new_string:
  it("returns null when no header carries a matching display name", () => {
    expect(findDisplayName(headers, new Set(["nobody@x.com"]))).toBeNull();
  });

  it("accepts a wildcard matcher, so an org file finds whoever is on the message", () => {
    expect(findDisplayName(headers, makeAddressMatcher(["@x.com"]))).toBe("Josh Harris");
  });
});

describe("describePerson", () => {
  const headers = [
    { name: "From", value: '"Melissa Rodriguez" <m@scrumalliance.org>' },
    { name: "To", value: "mark@felicisholdings.com" },
  ];

  it("pairs the display name with the address", () => {
    expect(describePerson(headers, "m@scrumalliance.org")).toBe(
      "Melissa Rodriguez <m@scrumalliance.org>"
    );
  });

  it("falls back to the bare address when there is no display name", () => {
    expect(describePerson(headers, "mark@felicisholdings.com")).toBe(
      "mark@felicisholdings.com"
    );
  });
});

describe("deriveDirection", () => {
  const org = makeAddressMatcher(["@protechtraining.com"]);

  it("labels Mark's own sent mail To {category}", () => {
    expect(deriveDirection(["SENT"], ["mark@felicisholdings.com"], org, "partner")).toBe(
      "To partner"
    );
  });

  it("labels mail from anyone at a wildcard domain From {category}", () => {
    expect(deriveDirection(["INBOX"], ["joe@protechtraining.com"], org, "partner")).toBe(
      "From partner"
    );
  });

  it("labels mail from a third party CC'd", () => {
    expect(deriveDirection(["INBOX"], ["stranger@elsewhere.com"], org, "partner")).toBe(
      "CC'd"
    );
  });
});

describe("buildQuery", () => {
  const base = { category: "partner", lastSearched: "2026-01-01" };

  it("drops the leading @ from a wildcard — Gmail searches the bare domain", () => {
    const q = buildQuery({ ...base, emails: ["@protechtraining.com"] }, "2026-08-05");
    expect(q).toBe(
      "after:2026/01/01 (from:(protechtraining.com) OR to:(protechtraining.com) OR cc:(protechtraining.com))"
    );
  });

  it("leaves exact addresses alone", () => {
    const q = buildQuery({ ...base, emails: ["josh@x.com"] }, "2026-08-05");
    expect(q).toContain("from:(josh@x.com)");
  });
});

describe("buildOwnershipMap / excludedFor", () => {
  const files = {
    "partners/protech.md": ["@protechtraining.com"],
    "partners/rodriguez-melissa.md": ["m@scrumalliance.org"],
    "partners/scrumalliance.md": ["@scrumalliance.org"],
    "client/harris-joshua.md": ["josh@clearandloud.com"],
  };
  const owners = buildOwnershipMap(Object.keys(files), (f) => files[f as keyof typeof files]);

  it("does not let a wildcard claim ownership of a domain", () => {
    expect(owners.has("@protechtraining.com")).toBe(false);
  });

  it("hands a person's own address back to their file, not the org file", () => {
    const excluded = excludedFor(
      { filePath: "partners/scrumalliance.md", matcher: makeAddressMatcher(["@scrumalliance.org"]) },
      owners
    );
    expect([...excluded]).toEqual(["m@scrumalliance.org"]);
  });

  it("excludes nothing for an org with no person files at its domain", () => {
    const excluded = excludedFor(
      { filePath: "partners/protech.md", matcher: makeAddressMatcher(["@protechtraining.com"]) },
      owners
    );
    expect(excluded.size).toBe(0);
  });

  it("never excludes an address the org file itself lists", () => {
    const owners2 = buildOwnershipMap(["partners/protech.md"], () => [
      "@protechtraining.com",
      "billing@protechtraining.com",
    ]);
    const excluded = excludedFor(
      {
        filePath: "partners/protech.md",
        matcher: makeAddressMatcher(["@protechtraining.com", "billing@protechtraining.com"]),
      },
      owners2
    );
    expect(excluded.size).toBe(0);
  });

  it("excludes nothing for a plain person contact", () => {
    const excluded = excludedFor(
      { filePath: "client/harris-joshua.md", matcher: makeAddressMatcher(["josh@clearandloud.com"]) },
      owners
    );
    expect(excluded.size).toBe(0);
  });
});

