const fs=require("fs"),path=require("path");
const {parseFrontmatterEmails,makeAddressMatcher}=require("./src/frontmatter");
const {buildOwnershipMap,excludedFor}=require("./src/gmail-sync");
const dirs=["client","colleagues","friends","partners"];
