const read=(f)=>{const raw=fs.readFileSync(f,"utf-8");const m=raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);return m?parseFrontmatterEmails(m[1].split(/\r?\n/)):[]};
const owners=buildOwnershipMap(files,read);
console.log("contact files:",files.length,"owned addresses:",owners.size);
for(const f of files.filter(f=>f.startsWith("partners/"))){
  const em=read(f);const mt=makeAddressMatcher(em);
  console.log(f,JSON.stringify(em),"wildcard:",mt.hasWildcard,"excluded:",[...excludedFor({filePath:f,matcher:mt},owners)]);
}
'

