// The single source of truth for contact categories.
//
// Adding a category is one row here — nothing else in the repo should hardcode
// a folder name. Before this table the list was duplicated across gmail-sync's
// discovery, its path→category mapping, its first-run floors, and
// create-contact's category flag, so a new folder half-worked: silently skipped
// by a full sync, and mislabelled "client" when passed by hand.
//
//   dir       the folder under the repo root
//   label     the singular word used in "Direction: From {label}" and in the
//             summary prompt. Not derivable from dir ("companies" → "companie")
//   yearsBack how far the FIRST sync of a contact in this category reaches.
//             Incremental runs ignore it — they're bounded by the contact's
//             cursor in .gmail-sync-state.json

export interface Category {
  dir: string;
  label: string;
  yearsBack: number;
}

export const CATEGORIES: Category[] = [
  { dir: "client", label: "client", yearsBack: 3 },
  { dir: "colleagues", label: "colleague", yearsBack: 3 },
  { dir: "friends", label: "friend", yearsBack: 10 },
  // Partner relationships run long — the same 10-year reach as friends.
  { dir: "partners", label: "partner", yearsBack: 10 },
];

// Fallback for a contact file that isn't under any known category folder.
const DEFAULT = CATEGORIES[0];

// Every directory that holds contact files, in scan order.
export const CONTACT_DIRS = CATEGORIES.map((c) => c.dir);

// Category label → folder, for create-contact's --category flag.
export const CATEGORY_DIRS: Record<string, string> = Object.fromEntries(
  CATEGORIES.map((c) => [c.label, c.dir])
);

// Match on a path *segment* so both relative ("friends/x.md") and absolute
// paths work — a "/friends/" substring test misses relative args.
export function categoryFor(contactPath: string): string {
  const segs = contactPath.replace(/\\/g, "/").split("/");
  return (CATEGORIES.find((c) => segs.includes(c.dir)) ?? DEFAULT).label;
}

export function yearsBackFor(label: string): number {
  return (CATEGORIES.find((c) => c.label === label) ?? DEFAULT).yearsBack;
}

