// gmail-sync-adjacent tooling uses for frontmatter scanning).
//
// A `@domain.com` org wildcard is matched only against other files' frontmatter
// entries, never as a substring: a person file at that domain is EXPECTED to
// coexist with the org file (the person's file wins for their own mail), so the
// substring match would wrongly call it a duplicate.
export function findExistingContact(email: string, root: string): string | null {
  const needle = email.toLowerCase();
  const wildcard = isDomainWildcard(needle);
  for (const dir of Object.values(CATEGORY_DIRS)) {
    const abs = path.join(root, dir);
    if (!fs.existsSync(abs)) continue;
    for (const f of fs.readdirSync(abs)) {
      if (!f.endsWith(".md")) continue;
      const raw = fs.readFileSync(path.join(abs, f), "utf-8");
      if (wildcard) {
        const fm = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
        const entries = fm ? parseFrontmatterEmails(fm[1].split(/\r?\n/)) : [];
        if (entries.includes(needle)) return `${dir}/${f}`;
      } else if (raw.toLowerCase().includes(needle)) {
        return `${dir}/${f}`;
      }
    }
  }
  return null;
}

export type CreateContactResult =
  | { status: "created"; relPath: string }
  | { status: "duplicate"; email: string; existing: string }
  | { status: "invalid-category" }
  | { status: "no-email" }
  | { status: "invalid-email"; email: string };

export interface CreateContactOptions {
  name: string;
  category: string;
  emails: string[];
  root: string;
  today: string;
  templatePath: string;
}

// Filesystem-touching core, parameterized by root/templatePath so callers
// (tests) can point it at a throwaway directory instead of the live repo.
export function createContact(opts: CreateContactOptions): CreateContactResult {
  const { name, category, emails, root, today, templatePath } = opts;

  if (!CATEGORY_DIRS[category]) return { status: "invalid-category" };
  if (emails.length === 0) return { status: "no-email" };
  for (const e of emails) {
    // "@domain.com" is a valid org wildcard; a bare "@" is not (it would match
    // every address there is).
    if (!e.includes("@") || e === "@") return { status: "invalid-email", email: e };
    if (isDomainWildcard(e) && !e.slice(1).includes("."))
      return { status: "invalid-email", email: e };
  }
  for (const e of emails) {
    const existing = findExistingContact(e, root);
    if (existing) return { status: "duplicate", email: e, existing };
  }

  // An org file's `--name` is a company, not a person: it goes in last_name
  // whole, so "ProTech Training" doesn't get split into a first and last name.
  const isOrg = emails.some(isDomainWildcard);
  const { firstName, lastName } = isOrg
    ? { firstName: "", lastName: name }
    : splitName(name);

  const dir = CATEGORY_DIRS[category];
  const dirAbs = path.join(root, dir);
  fs.mkdirSync(dirAbs, { recursive: true });
  const usedFilenames = new Set(
    fs.readdirSync(dirAbs).map((f) => f.replace(/\.md$/, ""))
  );
  const filename = makeFilename(lastName, firstName, emails[0], usedFilenames);

  const template = fs.readFileSync(templatePath, "utf-8");
  const body = template.slice(template.indexOf("\n## Notes"));
  const content = `${buildFrontmatter(lastName, firstName, emails, today)}\n${body}`;

  fs.writeFileSync(path.join(dirAbs, filename), content, "utf-8");
  return { status: "created", relPath: `${dir}/${filename}` };
