import { describe, it, expect } from "vitest";
import {
  CATEGORIES,
  CONTACT_DIRS,
  CATEGORY_DIRS,
  categoryFor,
  yearsBackFor,
} from "./categories";

describe("CATEGORIES table", () => {
  it("has a unique dir and label per row", () => {
    expect(new Set(CATEGORIES.map((c) => c.dir)).size).toBe(CATEGORIES.length);
    expect(new Set(CATEGORIES.map((c) => c.label)).size).toBe(CATEGORIES.length);
  });

  it("derives the scan dirs and the --category map from the one table", () => {
    expect(CONTACT_DIRS).toEqual(CATEGORIES.map((c) => c.dir));
    for (const c of CATEGORIES) expect(CATEGORY_DIRS[c.label]).toBe(c.dir);
  });
});

describe("categoryFor", () => {
  it("maps a folder to its singular label, relative or absolute", () => {
    expect(categoryFor("partners/ProTech.md")).toBe("partner");
    expect(categoryFor("/Users/mark/repo/colleagues/x.md")).toBe("colleague");
    expect(categoryFor("friends\\blyth-don.md")).toBe("friend"); // windows sep
  });

  it("matches a path segment, not a substring", () => {
    // "myfriends" is a different folder — it must not read as "friends".
    expect(categoryFor("myfriends/x.md")).toBe("client");
  });

  it("falls back to client for a file outside any category folder", () => {
    expect(categoryFor("scratch.md")).toBe("client");
  });
});

describe("yearsBackFor", () => {
  it("gives friends and partners the long 10-year first-run reach", () => {
    expect(yearsBackFor("friend")).toBe(10);
    expect(yearsBackFor("partner")).toBe(10);
  });

  it("keeps clients and colleagues at 3 years", () => {
    expect(yearsBackFor("client")).toBe(3);
    expect(yearsBackFor("colleague")).toBe(3);
  });

  it("falls back to the client floor for an unknown label", () => {
    expect(yearsBackFor("nonesuch")).toBe(3);
  });
});

